401	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
402	        refuseIfClosed(sheetId, claim.getDate());
403	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
404	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
405	        }
406	        if (claim.getStatus() != ClaimStatus.SETTLED) {
407	            throw new ResponseStatusException(HttpStatus.CONFLICT,
408	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
409	        }
410	        Person person = person(sheetId, claim.getPersonId());
411	        BigDecimal old = claim.getSettledDue();
412	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
413	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId),
414	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
415	        Rollup.Snapshot before = rollup.snapshot(sheetId);
416	        claim.setSettledDue(dueNow);
417	        logStatus(sheetId, user, person, claim);
418	        Claim saved = claims.saveAndFlush(claim);
419	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
420	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
421	        notifyWatchers(user, person, saved);
422	        rollup.recordChanges(user, before);
423	        return saved;
424	    }
425	
426	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
427	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
428	    @Transactional
429	    public Claim reject(String sheetId, String user, long id, String reason) {
430	        Claim claim = pending(sheetId, user, id);
431	        Person person = person(sheetId, claim.getPersonId());
432	        Rollup.Snapshot before = rollup.snapshot(sheetId);
433	        claim.setStatus(ClaimStatus.OPEN);
434	        logStatus(sheetId, user, person, claim);
435	        Claim saved = claims.saveAndFlush(claim);
436	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
437	        rollup.recordChanges(user, before);
438	        return saved;
439	    }
440	
441	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
442	     *  dated inside a closed period, or the user is not a steward of the sheet. */
443	    private Claim pending(String sheetId, String user, long id) {
444	        Claim claim = claims.findForUpdate(id, sheetId)
445	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
446	        refuseIfClosed(sheetId, claim.getDate());
447	        if (claim.getStatus() != ClaimStatus.PENDING) {
448	            throw new ResponseStatusException(HttpStatus.CONFLICT,
449	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
450	        }
451	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
452	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
453	        }
454	        return claim;
455	    }
456	
457	    /** How many days after its settlement a steward may still void a SETTLED claim. */
458	    private static final int VOID_SETTLED_DAYS = 7;
459	
460	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
461	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
462	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
463	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
464	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a settled claim.");
465	        }
466	        LocalDate settledOn = claim.settledOn();
467	        LocalDate today = sheets.today(sheetId);
468	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
469	            throw new ResponseStatusException(HttpStatus.CONFLICT,
470	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
471	        }
472	    }
473	
474	    /** The permission matrix's action for each status a claim is moved to by opening, settling or voiding it. */
475	    private static final Map<ClaimStatus, String> ACTIONS = Map.of(
476	            ClaimStatus.OPEN, "open", ClaimStatus.SETTLED, "settle", ClaimStatus.PENDING, "settle",
477	            ClaimStatus.VOID, "void");
478	
479	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
480	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
481	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
482	
483	    private static String text(BigDecimal due) {
484	        return due == null ? "n/a" : due.toPlainString();
485	    }
486	
487	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
488	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
489	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
490	    private String nextNumber(String sheetId, Claim claim) {
491	        if (!isPeriodNumbering(sheetId)) {
492	            return Integer.toString(sheets.nextClaimNumber(sheetId));
493	        }
494	        Period period = periodOf(sheetId, claim.getDate());
495	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
496	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
497	    }
498	
499	    /** Whether the sheet's period numbering is in force: its today on or after the setting's date. */
500	    private boolean isPeriodNumbering(String sheetId) {
501	        LocalDate from = settings.periodNumberingFrom(sheetId);
502	        return from != null && !sheets.today(sheetId).isBefore(from);
503	    }
504	
505	    /** The sheet's period whose dates contain the date; null when none does. */
506	    private Period periodOf(String sheetId, LocalDate date) {
507	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
508	                .filter((p) -> p.contains(date)).findFirst().orElse(null);
509	    }
510	
511	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
512	     *  in force on the claim's date (a due of n/a, or no threshold, needs none). */
513	    private void refuseIfUnproven(String sheetId, Claim claim, BigDecimal due) {
514	        if (due == null || claim.getProofs() > 0) return;
515	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
516	        if (threshold != null && due.compareTo(threshold) > 0) {
517	            throw new ResponseStatusException(HttpStatus.CONFLICT,
518	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
519	                            + "; add a proof before it is settled.");
520	        }
521	    }
522	
523	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
524	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
525	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
526	        BigDecimal limit = settings.clerkLimit(sheetId);
527	        return limit != null && due.compareTo(limit) > 0;
528	    }
529	
530	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
531	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
532	    private void refuseIfClosed(String sheetId, LocalDate date) {
533	        sheetRows.findForUpdate(sheetId);
534	        if (periods.isClosedOn(sheetId, date)) {
535	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
536	        }
537	    }
538	
539	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
540	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
541	        if (amount.signum() >= 0) return;
542	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
543	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
544	        if (!settled) {
545	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
546	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
547	        }
548	    }
549	
550	    /** Refuse a claim dated after its person's retirement date. */
551	    private static void refuseIfRetired(Person person, LocalDate date) {
552	        if (person.isRetiredOn(date)) {
553	            throw new ResponseStatusException(HttpStatus.CONFLICT,
554	                    "The claim is dated after " + person.getName() + " retired.");
555	        }
556	    }
557	
558	    private Person person(String sheetId, long personId) {
559	        return people.findByIdAndSheetId(personId, sheetId)
560	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
561	    }
562	
563	    /** What is due on the claim now: the due fixed when it was settled, else the greater of the floor in
564	     *  force on its date and its figure with the late charge on top while it is open and overdue (the charge
565	     *  is never bound by a statement; a correction has no floor); null when the figure is n/a. */
566	    public BigDecimal due(String sheetId, Person person, Claim claim) {
567	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), settings.floor(sheetId, claim.getDate()),
568	                sheets.today(sheetId),
569	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
570	    }
571	
572	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
573	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
574	     *  null when that is n/a. */
575	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
576	        if (claim.getSettledDue() != null) return claim.getSettledDue();
577	        if (claim.isBound()) return claim.getStatedDue();
578	        return dueNow(sheetId, person, claim);
579	    }
580	
581	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
582	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
583	     *  floor; null when no rate of the grade applies by then. */
584	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
585	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
586	        if (rate == null) return null;
587	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
588	                rounding(sheetId, claim));
589	    }
590	
591	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
592	     *  correction corrects, else by its own. */
593	    private RoundingMode rounding(String sheetId, Claim claim) {
594	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
595	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
596	                : null;
597	        return Rounding.of(Rounding.dateOf(claim, corrected),
598	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
599	    }
600	
601	    /** Log the status the claim has just taken, with its due as worked out now. */
602	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
603	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
604	    }
605	
606	    private void recordChange(String event, String user, Person person, Claim claim) {
607	        recordChange(event, user, person, claim, claim.getNumber(), "");
608	    }
609	
610	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
611	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
612	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
613	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
614	                + (number == null ? "" : " number=" + number) + extra);
615	    }
616	
617	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
618	    private void notifyWatchers(String user, Person person, Claim claim) {
619	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
620	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
621	                    + " person=" + person.getName() + " number=" + claim.getNumber());
622	        }
623	    }
624	
625	    private LocalDate dateOr(String sheetId, LocalDate date) {
626	        return date != null ? date : sheets.today(sheetId);
627	    }
628	
629	    private static String noteOf(String note) {
630	        return note == null ? "" : note.trim();
631	    }
632	}
