test("statement as of scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "grace-days", "3");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "20"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.periodAction(pg_uma, "P2", "soft-close")).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  const c_ben_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ben", "amount": "25.00"}, p_ben));
  expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-05")).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.retire(pg_uma, p_ben, "2026-03-15")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.editClaim(pg_uma, c_ben_0, {"amount": "0.40"})).toBe(false);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.periodAction(pg_wes, "P2", "reopen")).toBe(true);
  await ui.showRetired(pg_wes, true);
  expect(await ui.statement(pg_wes, p_ben)).toBe(true);
  expect(await ui.periodAction(pg_wes, "P2", "soft-close")).toBe(true);
  expect(await ui.setRate(pg_wes, {"grade": "C", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.claimAction(pg_wes, c_ben_0, "open")).toBe(true);
  await ui.refresh(pg_wes);
  await ui.refresh(pg_wes);
  expect(await ui.delegate(pg_wes, {"user": "uma", "from": "2026-03-01", "to": "2026-03-28"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_ben_0, "settle")).toBe(true);
  expect(await ui.retire(pg_uma, p_cam, "2026-03-05")).toBe(true);
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-03-09"})).toBeNull();
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Cam")).toBe(true);
  await ui.refresh(pg_uma);
  await ui.expectAudit(sheet, [
  ]);
});
